import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.math.BigInteger;

public final class EuclideanAlgorithmsTest {
    private static final String USAGE = """
        Usage: java EuclideanAlgorithms [first second]
        Prints the greatest common divisor of two integers.
        When no arguments are provided, defaults to 35 and 15.
        """.stripTrailing();

    private EuclideanAlgorithmsTest() {
    }

    public static void main(String[] args) {
        verifyAlgorithmCases();
        verifyRunCases();
    }

    private static void verifyAlgorithmCases() {
        AlgorithmCase[] cases = {
            new AlgorithmCase(BigInteger.valueOf(35), BigInteger.valueOf(15), BigInteger.valueOf(5), "gcd uses the default sample values"),
            new AlgorithmCase(BigInteger.valueOf(-24), BigInteger.valueOf(18), BigInteger.valueOf(6), "gcd normalizes negative inputs"),
            new AlgorithmCase(BigInteger.ZERO, BigInteger.valueOf(12), BigInteger.valueOf(12), "gcd handles a zero operand"),
            new AlgorithmCase(
                BigInteger.valueOf(Long.MIN_VALUE),
                BigInteger.ZERO,
                new BigInteger("9223372036854775808"),
                "gcd handles the absolute value overflow case"
            ),
            new AlgorithmCase(
                new BigInteger("9223372036854775808"),
                BigInteger.TWO,
                BigInteger.valueOf(2),
                "gcd supports integers larger than long"
            )
        };

        for (AlgorithmCase testCase : cases) {
            assertEquals(
                testCase.expected(),
                EuclideanAlgorithms.gcd(testCase.first(), testCase.second()),
                testCase.scenario()
            );
        }

        assertThrows(() -> EuclideanAlgorithms.gcd(0, 0), "gcd rejects two zero operands");
        assertThrows(() -> EuclideanAlgorithms.gcd((BigInteger) null, BigInteger.ONE), "gcd rejects a null first operand");
        assertThrows(() -> EuclideanAlgorithms.gcd(BigInteger.ONE, (BigInteger) null), "gcd rejects a null second operand");
    }

    private static void verifyRunCases() {
        RunCase[] cases = {
            new RunCase(new String[0], 0, "5\n", "", "run uses default operands"),
            new RunCase(new String[] {"--help"}, 0, USAGE + "\n", "", "run prints usage for help"),
            new RunCase(
                new String[] {"abc", "10"},
                1,
                "",
                "Invalid integer: abc\n" + USAGE + "\n",
                "run reports invalid input"
            ),
            new RunCase(
                new String[] {"1"},
                1,
                "",
                "Expected either zero arguments or exactly two integers.\n" + USAGE + "\n",
                "run rejects partial input"
            ),
            new RunCase(
                new String[] {"9223372036854775808", "2"},
                0,
                "2\n",
                "",
                "run supports integers larger than long"
            )
        };

        for (RunCase testCase : cases) {
            assertRun(testCase);
        }
    }

    private static void assertRun(RunCase testCase) {
        ByteArrayOutputStream stdoutBuffer = new ByteArrayOutputStream();
        ByteArrayOutputStream stderrBuffer = new ByteArrayOutputStream();
        int exitCode = EuclideanAlgorithms.run(
            testCase.args(),
            new PrintStream(stdoutBuffer),
            new PrintStream(stderrBuffer)
        );

        assertEquals(testCase.expectedExitCode(), exitCode, testCase.scenario() + ": exit code");
        assertEquals(testCase.expectedStdout(), stdoutBuffer.toString(), testCase.scenario() + ": stdout");
        assertEquals(testCase.expectedStderr(), stderrBuffer.toString(), testCase.scenario() + ": stderr");
    }

    private static void assertThrows(Runnable operation, String scenario) {
        try {
            operation.run();
            throw new AssertionError("Expected IllegalArgumentException: " + scenario);
        } catch (IllegalArgumentException expected) {
            // Expected path.
        }
    }

    private static void assertEquals(BigInteger expected, BigInteger actual, String scenario) {
        if (!expected.equals(actual)) {
            throw new AssertionError(scenario + ": expected " + expected + " but was " + actual);
        }
    }

    private static void assertEquals(int expected, int actual, String scenario) {
        if (expected != actual) {
            throw new AssertionError(scenario + ": expected " + expected + " but was " + actual);
        }
    }

    private static void assertEquals(String expected, String actual, String scenario) {
        if (!expected.equals(actual)) {
            throw new AssertionError(
                scenario + ": expected [" + expected + "] but was [" + actual + "]"
            );
        }
    }

    private record AlgorithmCase(
        BigInteger first,
        BigInteger second,
        BigInteger expected,
        String scenario
    ) {
    }

    private record RunCase(
        String[] args,
        int expectedExitCode,
        String expectedStdout,
        String expectedStderr,
        String scenario
    ) {
    }
}

import java.io.PrintStream;
import java.math.BigInteger;
public final class EuclideanAlgorithms {
    private static final CommandLine COMMAND_LINE = new CommandLine(
        BigInteger.valueOf(35),
        BigInteger.valueOf(15)
    );

    private EuclideanAlgorithms() {
        // Utility class.
    }

    public static BigInteger gcd(long first, long second) {
        return gcd(BigInteger.valueOf(first), BigInteger.valueOf(second));
    }

    public static BigInteger gcd(BigInteger first, BigInteger second) {
        return Operands.of(first, second).gcd();
    }

    public static void main(String[] args) {
        int exitCode = run(args, System.out, System.err);
        if (exitCode != 0) {
            System.exit(exitCode);
        }
    }

    static int run(String[] args, PrintStream out, PrintStream err) {
        return COMMAND_LINE.run(args, out, err);
    }

    private record Operands(BigInteger first, BigInteger second) {
        private static Operands of(BigInteger first, BigInteger second) {
            return new Operands(
                requireOperand(first, "first"),
                requireOperand(second, "second")
            );
        }

        private static BigInteger requireOperand(BigInteger operand, String name) {
            if (operand == null) {
                throw new IllegalArgumentException(name + " operand must not be null.");
            }

            return operand;
        }

        private BigInteger gcd() {
            BigInteger left = first.abs();
            BigInteger right = second.abs();

            if (left.equals(BigInteger.ZERO) && right.equals(BigInteger.ZERO)) {
                throw new IllegalArgumentException("At least one operand must be non-zero.");
            }

            while (!right.equals(BigInteger.ZERO)) {
                BigInteger remainder = left.remainder(right);
                left = right;
                right = remainder;
            }

            return left;
        }
    }

    private static final class CommandLine {
        private final Operands defaultOperands;

        private CommandLine(BigInteger defaultFirstOperand, BigInteger defaultSecondOperand) {
            defaultOperands = Operands.of(defaultFirstOperand, defaultSecondOperand);
        }

        private int run(String[] args, PrintStream out, PrintStream err) {
            try {
                Command command = parse(args);
                return command.execute(out);
            } catch (IllegalArgumentException exception) {
                err.println(exception.getMessage());
                err.println(usage());
                return 1;
            }
        }

        private Command parse(String[] args) {
            if (args.length == 0) {
                return new ComputeCommand(defaultOperands);
            }

            if (args.length == 1 && ("--help".equals(args[0]) || "-h".equals(args[0]))) {
                return new HelpCommand(usage());
            }

            if (args.length != 2) {
                throw new IllegalArgumentException("Expected either zero arguments or exactly two integers.");
            }

            return new ComputeCommand(Operands.of(parseInteger(args[0]), parseInteger(args[1])));
        }

        private BigInteger parseInteger(String value) {
            try {
                return new BigInteger(value);
            } catch (NumberFormatException exception) {
                throw new IllegalArgumentException("Invalid integer: " + value, exception);
            }
        }

        private String usage() {
            return "Usage: java EuclideanAlgorithms [first second]\n"
                + "Prints the greatest common divisor of two integers.\n"
                + "When no arguments are provided, defaults to "
                + defaultOperands.first()
                + " and "
                + defaultOperands.second()
                + ".";
        }
    }

    private sealed interface Command permits ComputeCommand, HelpCommand {
        int execute(PrintStream out);
    }

    private record ComputeCommand(Operands operands) implements Command {
        @Override
        public int execute(PrintStream out) {
            out.println(operands.gcd());
            return 0;
        }
    }

    private record HelpCommand(String usage) implements Command {
        @Override
        public int execute(PrintStream out) {
            out.println(usage);
            return 0;
        }
    }
}

